        # deterministic tie-break
        if sc > best_sc or (sc == best_sc and best is not None and (dx, dy) < best):
            best_sc = sc
            best = (dx, dy)

    if best is None:
        return [0, 0]
    return [int(best[0]), int(best[1])]

